    "from sklearn.cluster import MiniBatchKMeans\nfrom scipy.optimize import curve_fit\nfrom scipy.spatial.distance import pdist, squareform\nXY=xy/1000.0  # km\nnsub=len(XY)//100\nkm=MiniBatchKMeans(n_clusters=nsub,random_state=0,n_init=3,batch_size=4096).fit(XY)\nlab=km.labels_; cent=km.cluster_centers_\nprint(nsub, np.bincount(lab).min(), np.bincount(lab).max())\n\ndef expvg(h,c0,c1,a): return c0+c1*(1-np.exp(-3*h/a))\ndef emp_vg(P,z,nb=12):\n    D=pdist(P); G=0.5*pdist(z[:,None],'sqeuclidean')\n    mx=D.max()/2 if D.max()>0 else 1\n    bins=np.linspace(0,mx,nb+1); idx=np.digitize(D,bins)-1\n    h=[];g=[];n=[]\n    for b in range(nb):\n        s=idx==b\n        if s.sum()>=5: h.append(D[s].mean()); g.append(G[s].mean()); n.append(s.sum())\n    return np.array(h),np.array(g),np.array(n),mx\ndef fit_vg(P,z):\n    h,g,n,mx=emp_vg(P,z); v=max(np.var(z),1e-6)\n    if len(h)<3: return np.array([0.1*v,v,mx])\n    try:\n        p,_=curve_fit(expvg,h,g,p0=[0.1*v,v,mx/2],sigma=1/np.sqrt(n),\n                      bounds=([0,1e-9,1],[2*v,5*v,20*mx]),maxfev=3000)\n    except Exception: p=np.array([0.1*v,v,mx/2])\n    return p\ndef sim_vgs(P,z,S,rng):\n    p=fit_vg(P,z); D=squareform(pdist(P))\n    C=p[1]*np.exp(-3*D/p[2])+p[0]*np.eye(len(P))\n    L=np.linalg.cholesky(C+1e-9*np.eye(len(P))*p[1])\n    out=[p]\n    for s in range(S-1):\n        zs=L@rng.standard_normal(len(P))+z.mean()\n        out.append(fit_vg(P,zs))\n    return np.array(out)\nprint(fit_vg(XY[lab==0],om.temp.values[lab==0]))",
    "import time\ndef ebk(z, S=30, K=24, seed=0, targets=None, exclude_self=False):\n    rng=np.random.default_rng(seed)\n    vgs=[sim_vgs(XY[lab==c],z[lab==c],S,rng) for c in range(nsub)]\n    T=targets\n    ct=cKDTree(cent); _,tc=ct.query(T)\n    kk=K+1 if exclude_self else K\n    _,nb=cKDTree(XY).query(T,k=kk)\n    if exclude_self: nb=nb[:,1:]\n    pred=np.full(len(T),np.nan); se=np.full(len(T),np.nan)\n    for c in np.unique(tc):\n        s=np.nonzero(tc==c)[0]; idx=nb[s]; n=len(s)\n        P=XY[idx]                                  # n,K,2\n        Dij=np.linalg.norm(P[:,:,None,:]-P[:,None,:,:],axis=-1)\n        Di0=np.linalg.norm(P-T[s][:,None,:],axis=-1)\n        Z=z[idx]\n        preds=[];vars_=[]\n        for (c0,c1,a) in vgs[c]:\n            sill=c0+c1\n            Cij=c1*np.exp(-3*Dij/a)+c0*(Dij==0)\n            Ci0=c1*np.exp(-3*Di0/a)\n            A=np.ones((n,K+1,K+1)); A[:,:K,:K]=Cij; A[:,K,K]=0\n            b=np.ones((n,K+1)); b[:,:K]=Ci0\n            A[:,:K,:K]+=np.eye(K)*1e-8*sill\n            w=np.linalg.solve(A,b[...,None])[...,0]\n            preds.append((w[:,:K]*Z).sum(1))\n            vars_.append(sill-(w*b).sum(1))\n        preds=np.array(preds); vars_=np.clip(np.array(vars_),0,None)\n        pred[s]=preds.mean(0)\n        se[s]=np.sqrt(vars_.mean(0)+preds.var(0))\n    return pred,se\n# cross-validation on 2000 data points\ncvi=np.random.default_rng(1).choice(len(XY),2000,replace=False)\nfor f in ['temp','salinity']:\n    t0=time.time(); z=om[f].values\n    p,s=ebk(z,S=10,targets=XY[cvi],exclude_self=True)\n    e=p-z[cvi]; print(f,'RMSE',np.sqrt(np.mean(e**2)),'MAE',np.mean(np.abs(e)),'R2',1-np.var(e)/np.var(z[cvi]),'std z',np.mean(e/s),np.sqrt(np.mean((e/s)**2)),time.time()-t0)",
    "import warnings; warnings.filterwarnings('ignore')\nT=np.c_[cx,cy]/1000.0\nprof=dict(driver='GTiff',height=H,width=W,count=1,dtype='float32',crs=om.crs,transform=tr,nodata=-9999,compress='lzw')\nrast={}\nfor f in ['temp','salinity']:\n    t0=time.time()\n    p,s=ebk(om[f].values,S=30,targets=T,seed=7)\n    a=np.full((H,W),-9999,np.float32); a[rows,cols]=p\n    e=np.full((H,W),-9999,np.float32); e[rows,cols]=s\n    with rasterio.open(f'pred_results/EBK_{f}.tif','w',**prof) as dst: dst.write(a,1)\n    with rasterio.open(f'pred_results/EBK_{f}_stderr.tif','w',**prof) as dst: dst.write(e,1)\n    rast[f]=np.where(a==-9999,np.nan,a)\n    print(f,np.nanmin(p),np.nanmax(p),time.time()-t0)",
