    "from sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold\nPv=np.c_[ptemp,psal][in_study]; Bv=np.c_[rast['temp'][br,bc],rast['salinity'][br,bc]]\nXraw=np.vstack([Pv,Bv]); yv=np.r_[np.ones(len(Pv)),np.zeros(len(Bv))]\nmu=Bv.mean(0); sd=Bv.std(0)\nknots=[np.quantile((Bv[:,j]-mu[j])/sd[j],np.linspace(0.05,0.95,15)) for j in range(2)]\ndef feats(V):\n    Zs=(V-mu)/sd; F=[Zs,Zs**2,(Zs[:,0]*Zs[:,1])[:,None]]\n    for j in range(2):\n        k=knots[j]; F.append(np.maximum(0,Zs[:,[j]]-k)); F.append(np.maximum(0,k-Zs[:,[j]]))\n    return np.hstack(F)\nXf=feats(Xraw); fsd=Xf[yv==0].std(0)+1e-9; fmu=Xf[yv==0].mean(0)\nXs=(Xf-fmu)/fsd\nsw=np.where(yv==1,1.0,100.0)\nskf=StratifiedKFold(5,shuffle=True,random_state=0)\nfor C in [0.001,0.003,0.01,0.03,0.1,1]:\n    aucs=[]\n    for a,b in skf.split(Xs,yv):\n        m=LogisticRegression(penalty='l1',C=C,solver='liblinear',max_iter=2000).fit(Xs[a],yv[a],sample_weight=sw[a])\n        aucs.append(roc_auc_score(yv[b],m.decision_function(Xs[b])))\n    print(C,np.mean(aucs).round(4),(m.coef_!=0).sum())",
    "mdl=LogisticRegression(penalty='l1',C=0.01,solver='liblinear',max_iter=5000).fit(Xs,yv,sample_weight=sw)\nlo,hi=Bv.min(0),Bv.max(0)\ndef maxent_prob(V):\n    V=np.clip(V,lo,hi)  # clamping\n    return (( (feats(V)-fmu)/fsd) @ mdl.coef_[0])\neta_bg=maxent_prob(Bv); mx_=eta_bg.max()\nlse=mx_+np.log(np.exp(eta_bg-mx_).sum())\nrawbg=np.exp(eta_bg-lse); Hent=-(rawbg*np.log(rawbg)).sum()\ndef cloglog(V): return 1-np.exp(-np.exp(maxent_prob(V)-lse+Hent))\npp=cloglog(Pv); pb=cloglog(Bv)\nauc=roc_auc_score(yv,np.r_[pp,pb]); print('train AUC',auc,'entropy',Hent)\nfrom sklearn.metrics import roc_curve\nfpr,tpr,th=roc_curve(yv,np.r_[pp,pb]); cut=th[np.argmax(tpr-fpr)]\nprint('cutoff',cut,'sens',(pp>=cut).mean(),'bg pred presence',(pb>=cut).mean())\nnz=mdl.coef_[0]!=0; print('nonzero features',nz.sum())",
    "P_xy=pts[in_study]\ntf=gpd.GeoDataFrame({\n 'TRAINED_ID':np.arange(1,len(yv)+1),\n 'PRESENCE':yv.astype(int),\n 'TEMP':Xraw[:,0],'SALINITY':Xraw[:,1],\n 'PROB_PRES':np.r_[pp,pb],\n 'PRED_PRES':(np.r_[pp,pb]>=cut).astype(int)},\n geometry=gpd.points_from_xy(np.r_[P_xy[:,0],bx],np.r_[P_xy[:,1],by]),crs=om.crs)\ntf['FIT_TYPE']=np.where((tf.PRESENCE==1)&(tf.PRED_PRES==1),'Presence-Correct',\n               np.where(tf.PRESENCE==1,'Presence-Incorrect',np.where(tf.PRED_PRES==1,'Background-Predicted Presence','Background-Predicted Background')))\ntf.to_file('pred_results/seagrass_trained_features.shp')\nprint(tf.FIT_TYPE.value_counts())\nV=np.c_[rast['temp'][gmask],rast['salinity'][gmask]]\nprob=np.full((H,W),-9999,np.float32); prob[gmask]=cloglog(V)\ncls=np.full((H,W),255,np.uint8); cls[gmask]=(prob[gmask]>=cut).astype(np.uint8)\nwith rasterio.open('pred_results/seagrass_prediction_probability.tif','w',**prof) as dst: dst.write(prob,1)\np2=dict(prof,dtype='uint8',nodata=255)\nwith rasterio.open('pred_results/seagrass_prediction_class.tif','w',**p2) as dst: dst.write(cls,1)\nprint('global cells predicted presence:',cls[gmask].mean())",
    'import matplotlib; matplotlib.use(\'Agg\'); import matplotlib.pyplot as plt\next=[x0,x1,y0,y1]\nfig,ax=plt.subplots(2,2,figsize=(18,10))\nfor a_,(arr,ttl,cm) in zip(ax.flat[:3],[(rast[\'temp\'],\'EBK temperature (°C)\',\'coolwarm\'),(rast[\'salinity\'],\'EBK salinity\',\'viridis\'),(np.where(prob==-9999,np.nan,prob),\'MaxEnt seagrass probability of presence\',\'YlGn\')]):\n    im=a_.imshow(arr,extent=ext,cmap=cm); a_.set_title(ttl); plt.colorbar(im,ax=a_,shrink=0.7)\na_=ax[1,1]; im=a_.imshow(np.where(prob==-9999,np.nan,prob),extent=ext,cmap=\'YlGn\',vmin=0,vmax=1)\nsgd.boundary.plot(ax=a_,color=\'red\',lw=0.4); rp.sample(1000,random_state=0).plot(ax=a_,markersize=1,color=\'k\')\nb=usw.total_bounds; a_.set_xlim(b[0],b[2]); a_.set_ylim(b[1],b[3]); a_.set_title(\'USA study area: probability + seagrass (red) + random points\')\nplt.tight_layout(); plt.savefig(\'pred_results/seagrass_maxent_overview.png\',dpi=110); plt.close()\nrep=f"""Seagrass habitat prediction workflow\n1. USA_seagrass dissolved -> USA_seagrass_dissolved.shp ; 5000 random points inside -> seagrass_random_points.shp\n2. EBK-style kriging (subsets ~100 pts, 331 subsets, exponential+nugget semivariogram, 30 simulated semivariograms/subset, 24-neighbour local ordinary kriging averaged over simulations), 10 km grid, EPSG:8857, masked to shallow waters.\n   Cross-validation (2000 pts): temp RMSE 0.58 R2 0.998 ; salinity RMSE 0.58 R2 0.990\n   Outputs: EBK_temp.tif, EBK_salinity.tif (+ _stderr.tif)\n3. MaxEnt (maxnet formulation: L1 logistic, linear/quadratic/product/hinge features, background weight 100, cloglog output, clamping)\n   Study area: USA_shallow_waters ; presence points in study area: {len(Pv)} ; background cells: {len(Bv)}\n   Training AUC {auc:.3f} ; 5-fold CV AUC ~0.835 ; cutoff (max sens+spec) {cut:.3f} ; sensitivity {(pp>=cut).mean():.3f}\n   Outputs: seagrass_trained_features.shp, seagrass_prediction_probability.tif, seagrass_prediction_class.tif (global shallow waters)\n"""\nopen(\'pred_results/README.txt\',\'w\').write(rep); print(rep); print(sorted(os.listdir(\'pred_results\')))',
